"""Port design preview sheet 06 (Records & Data Sources) into live modules.
Writes: sheet-records.css, sheet-records-sections.js, sheet-records-page.js (repo root).
The backup, sync and vault sections are filled by the Office's own working components at mount time
(sheet-records-page.js moves them in); the preview's static placeholders for them are dropped."""
import os, re, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import sheetport as SP
repo = sys.argv[1]; P = lambda *a: os.path.join(repo, *a); D = lambda f: SP.rd(P('design', 'preview', f)); rep = SP.rep
html = D('records.html')
inline = html[html.index('<style>') + 7:html.index('</style>')]
css = SP.scope_block('\n'.join([inline, D('office-ui.css'), D('macro-sections.css'), D('markets.css'), D('research.css'), D('identity.css')]), '.lh-sheet-records')
extra = ('/* the Office components placed in the backup, sync and vault sections */\n'
         '.lh-sheet-records .lh-embedded{display:grid;gap:16px;margin-top:14px}\n'
         '.lh-sheet-records .lh-embedded>section{margin:0;padding:16px 18px;border:1px solid var(--rule);border-radius:4px;background:color-mix(in srgb,var(--sheet) 70%,transparent);box-shadow:none}\n'
         '.lh-sheet-records .lh-embedded .lh-intro-hidden>.eyebrow,.lh-sheet-records .lh-embedded .lh-intro-hidden>.eyebrow+h2,.lh-sheet-records .lh-embedded .lh-intro-hidden>.eyebrow+h2+p{display:none}\n')
SP.wr(P('sheet-records.css'), '/* Sheet 06 Records & Data Sources, ported from design/preview (records.html and the shared preview CSS).\n'
      '   Scoped to .lh-sheet-records. Generated by design/build/port/port_records.py. */\n' + css + SP.bindings('.lh-sheet-records') + extra)

s = D('records.js')
s = rep(s, "(function(){", "export function mountRecordsSections(){", 1) if s.startswith('// ') is False else s
if not s.lstrip().startswith('export'):
    i = s.index('(function(){'); s = s[:i] + 'export function mountRecordsSections(){' + s[i + len('(function(){'):]
s = s.rstrip(); assert s.endswith('})();'); s = s[:-5] + '}\n'
s = rep(s, "document.readyState==='loading'?document.addEventListener('DOMContentLoaded',all):all();", "all();")
s = rep(s, "${state.show==='all'?' This preview carries every record that needs attention plus up to 40 healthy records per area; the live app lists all 9,004.':''}",
        "${state.show==='all'?' This sheet lists every record that needs attention plus up to 40 healthy records per area; <a href=\"#data-sources\">Data Sources</a> lists them all.':''}")
s = rep(s, "<em>No successful source read in this preview session</em>", "<em>Sources are read in Data Sources, on request</em>")
s = rep(s, "<button class=\"btn-line\" disabled title=\"Reads a source in the live app\">Load selected source</button>", "<a class=\"btn-line\" href=\"#data-sources\">Load a source in Data Sources →</a>")
s = rep(s, "'Larger than 5 MB — not inspected in the preview'", "'Larger than 5 MB — not inspected here'")
for a, b in [("'macro.html#pulse'", "'#macro'"), ("'macro.html#rates'", "'#macro'"), ("'macro.html#calendar'", "'#macro'"), ("'markets.html#bonds'", "'#markets'"), ("'macro.html#compare'", "'#macro'"), ("'macro.html#region'", "'#macro'")]:
    s = rep(s, a, b)
# backup, sync and vault: keep the preview's section heading only; the Office components are placed below it on mount
for name in ('backup', 'sync', 'vault'):
    a = s.index('function ' + name + '(){'); b = s.index('\n}\n', a) + 3
    body = s[a:b]; h = body.index("head("); end = body.index(")+", h) + 1
    s = s[:a] + 'function ' + name + "(){\n  $('#" + name + " .panel').innerHTML=" + body[h:end] + "+'<div class=\"lh-embedded\" data-embed=\"" + name + "\"></div>';\n}\n" + s[b:]
assert 'live app' not in s and 'preview' not in s.lower().replace('design/preview', ''), [l for l in s.split('\n') if 'live app' in l or 'preview' in l.lower()]
assert not re.search(r"""['"](index|macro|markets|research|portfolio|records)\.html""", s), 'a link to a preview page is left'
SP.wr(P('sheet-records-sections.js'), "// Sheet 06 Records & Data Sources: every section, rendered from the published sheet data (window.RECORDS).\n// Ported from design/preview/records.js. Backup, sync and vault hold the Office's own working components.\n" + s)

body = html[html.index('<nav class="mtabs"'):html.index('<footer>')].replace('<main>', '<div class="lh-sheet-body">').replace('</main>', '</div>')
assert '`' not in body and '${' not in body
foot = '<div class="lh-sheet-foot"><span>Coverage: the Office public-data report, with the same attention rules as Data Sources.</span><span>No analytics or tracking. Nothing on this sheet uploads your records.</span></div>'
js = ("// Sheet 06 Records & Data Sources: page markup and mount. Markup from design/preview/records.html; the header is the Office's own.\n"
      "// The Office's working backup, checkpoint-sync and vault components are rendered (hidden) with the page so their own\n"
      "// mounts run unchanged, then moved into the sheet's sections. Nothing about how they save, restore or export changes.\n"
      "import {loadSheetData,hostSheet} from './sheet-host.js';\nimport {mountRecordsSections} from './sheet-records-sections.js';\nimport {mountSheetViews} from './sheet-views.js';\n"
      "let host=null;\n"
      "export function recordsSheetPage(live){return `<div class=\"lh-sheet lh-sheet-records\" data-sheet=\"records\">" + re.sub(r'\n\s*', '', body) + foot + "</div><div class=\"lh-live-holder\" hidden>${live}</div>`;}\n"
      "const PLACE={backup:[['.complete-backup',true],['.records-panel > section:nth-of-type(2)',false]],sync:[['.private-vault-panel',true]],vault:[['.records-panel > section:nth-of-type(1)',false],['.vault-panel',false],['.workspace-health',false],['.records-panel > section:nth-of-type(3)',false]]};\n"
      "function placeLive(root){\n"
      " const holder=root.parentElement.querySelector('.lh-live-holder');if(!holder)return;\n"
      " for(const [name,parts] of Object.entries(PLACE)){const slot=root.querySelector(`[data-embed=\"${name}\"]`);if(!slot)continue;\n"
      "  // the sheet's heading already says what the component's own intro says\n"
      "  for(const [selector,intro] of parts){const el=holder.querySelector(selector);if(!el)continue;if(intro)el.classList.add('lh-intro-hidden');slot.append(el);}\n"
      "  if(!slot.children.length)slot.innerHTML='<p class=\"src\">This part of the workspace is not available in this edition of the Office.</p>';}\n"
      "}\n"
      "export async function mountRecordsSheet(){\n"
      " const root=document.querySelector('[data-sheet=\"records\"]');if(!root)return;host?.stop();host=hostSheet(root);const own=host;\n"
      " try{await loadSheetData(['records-sheet']);}\n"
      " catch{if(root.isConnected){const holder=root.parentElement.querySelector('.lh-live-holder');if(holder)holder.hidden=false;root.querySelector('.lead-sec .dek').textContent='The published coverage report could not be read. Your backup and vault tools are below.';}return;}\n"
      " if(!root.isConnected||own!==host)return;\n"
      " mountRecordsSections();placeLive(root);mountSheetViews(host.listen,'records');\n"
      "}\n")
SP.wr(P('sheet-records-page.js'), js)
print('records css', len(css), 'sections', len(s))
